'use strict';
const QUIZ_STORE='kienhoc-progress-v2';
const QuizStore=(()=>{
 const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
 const empty=()=>({version:1,progress:{},bookmarks:[],session:null,prefs:{sound:true,speechRate:.9},_sync:{bookmarks:{},sessionAt:0,resetAt:0,prefsAt:0}});
 const root=()=>({version:2,history:empty(),ai:empty(),information:empty()});
 function clean(s,id){s=s&&typeof s==='object'?s:empty();const out={...empty(),...s,progress:{},bookmarks:[]};for(const[k,v]of Object.entries(s.progress||{}))if(BYKEY[k]?.subject===id&&v&&Number.isFinite(v.attempts)&&v.attempts>=0)out.progress[k]={...v,correct:Math.max(0,Math.min(v.attempts,Number(v.correct)||0)),last:isGradable(BYKEY[k])?(v.lastAnswer?isCorrect(BYKEY[k],v.lastAnswer):typeof v.last==='boolean'?v.last:false):null};const rate=Number(out.prefs?.speechRate);out.prefs={sound:out.prefs?.sound!==false,speechRate:rate>=.6&&rate<=1.5?rate:.9};out._sync=out._sync&&typeof out._sync==='object'?out._sync:{bookmarks:{}};out._sync.bookmarks||={};out.bookmarks=(Array.isArray(s.bookmarks)?s.bookmarks:[]).filter(k=>BYKEY[k]?.subject===id);const se=s.session;if(!se||se.subject!==id||!Array.isArray(se.keys)||!se.keys.length||!se.keys.every(k=>BYKEY[k]?.subject===id)||!Number.isInteger(se.index)||se.index<0||se.index>=se.keys.length||!['learn','exam'].includes(se.mode)||!se.answers||typeof se.answers!=='object')out.session=null;else {out.session={...se,answers:Object.fromEntries(Object.entries(se.answers).filter(([k,v])=>se.keys.includes(k)&&BYKEY[k]?.options['ABCD'.indexOf(v)])),created:Number.isSafeInteger(se.created)&&se.created>=0?se.created:0,deadline:Number.isSafeInteger(se.deadline)&&se.deadline>=0?se.deadline:null};}return out;}
 function legacyHistory(old){const h=empty();h.prefs={...h.prefs,...old.prefs};for(const[k,v]of Object.entries(old.progress||{})){const q=BYKEY['history.'+k];if(q)h.progress[q.key]=v;}h.bookmarks=(old.bookmarks||[]).map(k=>'history.'+k).filter(k=>BYKEY[k]);if(old.session){const se=old.session;h.session={...se,subject:'history',keys:(se.keys||[]).map(k=>'history.'+k),answers:Object.fromEntries(Object.entries(se.answers||{}).map(([k,v])=>['history.'+k,v])),hints:Object.fromEntries(Object.entries(se.hints||{}).map(([k,v])=>['history.'+k,v])),hintsUsed:Object.fromEntries(Object.entries(se.hintsUsed||{}).map(([k,v])=>['history.'+k,v]))};}return clean(h,'history');}
 function migrate(){const d=read(QUIZ_STORE,null);if(d?.version===2){for(const id of Object.keys(QUIZ_DATA))d[id]=clean(d[id],id);return d;}const x=root();x.history=legacyHistory(read('su-ky-progress-v1',{}));for(const [id,key]of [['ai','kienhoc-ai-choices-v1'],['information','kienhoc-info-choices-v1']])for(const[n,a]of Object.entries(read(key,{}))){const q=BYKEY[id+'.'+n];if(!q||!q.options['ABCD'.indexOf(a)])continue;x[id].progress[q.key]={attempts:1,correct:isCorrect(q,a)?1:0,last:isGradable(q)?isCorrect(q,a):null,lastAnswer:a,at:0};}return x;}
 function legacyProjection(d){const h=d.history;const map=o=>Object.fromEntries(Object.entries(o||{}).map(([k,v])=>[k.replace(/^history\./,''),v]));return {...h,progress:map(h.progress),bookmarks:h.bookmarks.map(k=>k.replace(/^history\./,'')),session:h.session?{...h.session,keys:h.session.keys.map(k=>k.replace(/^history\./,'')),answers:map(h.session.answers),hints:map(h.session.hints),hintsUsed:map(h.session.hintsUsed)}:null,_sync:{...(read('su-ky-progress-v1',{})._sync||{}),bookmarks:map(h._sync?.bookmarks),sessionAt:h._sync?.sessionAt||0,prefsAt:h._sync?.prefsAt||0,resetAt:h._sync?.resetAt||0}};}
 function persist(d){localStorage.setItem(QUIZ_STORE,JSON.stringify(d));localStorage.setItem('su-ky-progress-v1',JSON.stringify(legacyProjection(d)));for(const[id,key]of [['ai','kienhoc-ai-choices-v1'],['information','kienhoc-info-choices-v1']])localStorage.setItem(key,JSON.stringify(Object.fromEntries(Object.entries(d[id].progress).filter(([k,v])=>BYKEY[k]?.origin==='pdf'&&v.lastAnswer).map(([k,v])=>[BYKEY[k].number,v.lastAnswer]))));}
 function validBackup(d){const valid=s=>s&&typeof s==='object'&&s.progress&&typeof s.progress==='object'&&!Array.isArray(s.progress)&&Array.isArray(s.bookmarks)&&Object.values(s.progress).every(p=>p&&Number.isSafeInteger(p.attempts)&&p.attempts>=0&&Number.isFinite(p.correct)&&p.correct>=0&&p.correct<=p.attempts);return d?.version===1?valid(d):d?.version===2&&['history','ai','information'].every(id=>valid(d[id]));}
 function importState(s,id){const out=clean(s,id),now=Date.now();out._sync.resetAt=now;out._sync.sessionAt=now+1;out._sync.prefsAt=now+1;for(const p of Object.values(out.progress))p.at=now+1;out._sync.bookmarks=Object.fromEntries(out.bookmarks.map(k=>[k,{value:true,at:now+1}]));return out;}
 return {validBackup,importState,read,migrate,clean,empty,root,persist,legacyHistory};
})();
